6	  account_id = var.cloudflare_account_id
7	  name       = "raven-demo"
8	  secret     = random_id.tunnel_secret.b64_std
9	}
10	
11	resource "cloudflare_tunnel_config" "demo" {
12	  account_id = var.cloudflare_account_id
13	  tunnel_id  = cloudflare_tunnel.demo.id
14	
15	  config {
16	    ingress_rule {
17	      hostname = var.demo_hostname
18	      service  = "http://localhost:8180"
19	      path     = "/api/.*"
20	    }
21	    ingress_rule {
22	      hostname = var.demo_hostname
23	      service  = "http://localhost:8080"
24	    }
25	    ingress_rule {
26	      hostname = var.observability_hostname
27	      service  = "http://localhost:5080"
28	    }
29	    ingress_rule {
30	      service = "http_status:404"
31	    }
32	  }
33	}
34	
35	resource "cloudflare_record" "demo" {
36	  zone_id = var.cloudflare_zone_id
37	  name    = var.demo_hostname
38	  content = "${cloudflare_tunnel.demo.id}.cfargotunnel.com"
39	  type    = "CNAME"
40	  proxied = true
41	}
42	
43	resource "cloudflare_record" "observability" {
44	  zone_id = var.cloudflare_zone_id
45	  name    = var.observability_hostname
46	  content = "${cloudflare_tunnel.demo.id}.cfargotunnel.com"
47	  type    = "CNAME"
48	  proxied = true
49	}
50	
51	# Cloudflare Access: gate observability subdomain to your email only
52	resource "cloudflare_access_application" "observability" {
53	  account_id       = var.cloudflare_account_id
54	  name             = "raven-demo-observability"
55	  domain           = var.observability_hostname
56	  session_duration = "24h"
57	}
58	
59	resource "cloudflare_access_policy" "observability_allow" {
60	  account_id     = var.cloudflare_account_id
61	  application_id = cloudflare_access_application.observability.id
62	  name           = "allow-operator"
63	  precedence     = 1
64	  decision       = "allow"
65	
66	  include {
67	    email = [var.access_email]
68	  }
69	}
70	
71	# Phase 1 gate on the whole demo hostname — set var.phase1_access_enabled=false to lift.
